insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-k-pop-groups-trivia',
  'K-Pop Groups Trivia: BTS, BLACKPINK, TWICE and the Legends',
  'Eight questions on the groups that built K-pop: debut years, fandom names and the terms every fan knows, from EXO to Girls'' Generation.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"In which year did BTS make their official debut?","options":[{"id":"a","text":"2007","is_correct":false},{"id":"b","text":"2010","is_correct":false},{"id":"c","text":"2013","is_correct":true},{"id":"d","text":"2016","is_correct":false}],"explanation":"BTS debuted on 13 June 2013 under Big Hit Entertainment with the single album 2 Cool 4 Skool."},{"id":"q2","question":"What is the official name of BLACKPINK''s fandom?","options":[{"id":"a","text":"ONCE","is_correct":false},{"id":"b","text":"BLINK","is_correct":true},{"id":"c","text":"ARMY","is_correct":false},{"id":"d","text":"MIDZY","is_correct":false}],"explanation":"BLINK combines the beginning and end of BLACKPINK; ONCE belongs to TWICE and ARMY to BTS."},{"id":"q3","question":"TWICE was formed in 2015 through which JYP survival show?","options":[{"id":"a","text":"Sixteen","is_correct":true},{"id":"b","text":"Produce 101","is_correct":false},{"id":"c","text":"K-pop Star","is_correct":false},{"id":"d","text":"I-Land","is_correct":false}],"explanation":"Sixteen aired in 2015 and chose the nine members of TWICE, who debuted that October with Like Ooh-Ahh."},{"id":"q4","question":"Which company debuted EXO in 2012?","options":[{"id":"a","text":"YG Entertainment","is_correct":false},{"id":"b","text":"JYP Entertainment","is_correct":false},{"id":"c","text":"Big Hit Entertainment","is_correct":false},{"id":"d","text":"SM Entertainment","is_correct":true}],"explanation":"SM launched EXO in April 2012 as two sub-units, EXO-K and EXO-M, promoting in Korean and Mandarin."},{"id":"q5","question":"In which year did Girls'' Generation debut?","options":[{"id":"a","text":"2005","is_correct":false},{"id":"b","text":"2007","is_correct":true},{"id":"c","text":"2009","is_correct":false},{"id":"d","text":"2011","is_correct":false}],"explanation":"Girls'' Generation (SNSD) debuted on 5 August 2007 under SM Entertainment and became the defining girl group of their era."},{"id":"q6","question":"In K-pop slang, what does ''maknae'' mean?","options":[{"id":"a","text":"The group leader","is_correct":false},{"id":"b","text":"The main dancer","is_correct":false},{"id":"c","text":"The youngest member","is_correct":true},{"id":"d","text":"The oldest member","is_correct":false}],"explanation":"Maknae (막내) is the youngest member of a group, often known for playful charm — a fixed role in K-pop."},{"id":"q7","question":"Which 2012 hit became the first YouTube video ever to reach one billion views?","options":[{"id":"a","text":"Fantastic Baby — BIGBANG","is_correct":false},{"id":"b","text":"Gee — Girls'' Generation","is_correct":false},{"id":"c","text":"Sorry, Sorry — Super Junior","is_correct":false},{"id":"d","text":"Gangnam Style — Psy","is_correct":true}],"explanation":"Gangnam Style passed one billion views in December 2012, a milestone YouTube had never seen before."},{"id":"q8","question":"What is the official name of BTS''s fandom?","options":[{"id":"a","text":"EXO-L","is_correct":false},{"id":"b","text":"SONE","is_correct":false},{"id":"c","text":"ARMY","is_correct":true},{"id":"d","text":"VIP","is_correct":false}],"explanation":"ARMY stands for Adorable Representative M.C. for Youth; EXO-L is EXO''s fandom and VIP is BIGBANG''s."}]'::jsonb,
  null,
  array['k-pop', 'trivia', 'pop culture', 'music', 'korea']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
