values (
  'es-trivia-grupos-de-k-pop',
  'Trivia de grupos de K-pop: BTS, BLACKPINK, TWICE y las leyendas',
  'Ocho preguntas sobre los grupos que construyeron el K-pop: años de debut, nombres de fandom y los términos que todo fan conoce.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"¿En qué año debutó oficialmente BTS?","options":[{"id":"a","text":"2007","is_correct":false},{"id":"b","text":"2010","is_correct":false},{"id":"c","text":"2013","is_correct":true},{"id":"d","text":"2016","is_correct":false}],"explanation":"BTS debutó el 13 de junio de 2013 bajo Big Hit Entertainment con el sencillo 2 Cool 4 Skool."},{"id":"q2","question":"¿Cómo se llama oficialmente el fandom de BLACKPINK?","options":[{"id":"a","text":"ONCE","is_correct":false},{"id":"b","text":"BLINK","is_correct":true},{"id":"c","text":"ARMY","is_correct":false},{"id":"d","text":"MIDZY","is_correct":false}],"explanation":"BLINK une el inicio y el final de BLACKPINK; ONCE es el fandom de TWICE y ARMY el de BTS."},{"id":"q3","question":"TWICE se formó en 2015 gracias a qué programa de supervivencia de JYP?","options":[{"id":"a","text":"Sixteen","is_correct":true},{"id":"b","text":"Produce 101","is_correct":false},{"id":"c","text":"K-pop Star","is_correct":false},{"id":"d","text":"I-Land","is_correct":false}],"explanation":"Sixteen se emitió en 2015 y eligió a las nueve integrantes de TWICE, que debutaron ese octubre con Like Ooh-Ahh."},{"id":"q4","question":"¿Qué compañía lanzó a EXO en 2012?","options":[{"id":"a","text":"YG Entertainment","is_correct":false},{"id":"b","text":"JYP Entertainment","is_correct":false},{"id":"c","text":"Big Hit Entertainment","is_correct":false},{"id":"d","text":"SM Entertainment","is_correct":true}],"explanation":"SM estrenó a EXO en abril de 2012 con dos subunidades, EXO-K y EXO-M, para Corea y el mercado en mandarín."},{"id":"q5","question":"¿En qué año debutó Girls'' Generation?","options":[{"id":"a","text":"2005","is_correct":false},{"id":"b","text":"2007","is_correct":true},{"id":"c","text":"2009","is_correct":false},{"id":"d","text":"2011","is_correct":false}],"explanation":"Girls'' Generation (SNSD) debutó el 5 de agosto de 2007 bajo SM Entertainment y marcó a toda una generación."},{"id":"q6","question":"En la jerga del K-pop, ¿qué significa ''maknae''?","options":[{"id":"a","text":"El líder del grupo","is_correct":false},{"id":"b","text":"El bailarín principal","is_correct":false},{"id":"c","text":"El miembro más joven","is_correct":true},{"id":"d","text":"El miembro más veterano","is_correct":false}],"explanation":"Maknae (막내) es el integrante menor del grupo, un rol fijo en el K-pop que suele darle encanto al conjunto."},{"id":"q7","question":"¿Qué éxito de 2012 fue el primer video de YouTube en llegar a mil millones de vistas?","options":[{"id":"a","text":"Fantastic Baby — BIGBANG","is_correct":false},{"id":"b","text":"Gee — Girls'' Generation","is_correct":false},{"id":"c","text":"Sorry, Sorry — Super Junior","is_correct":false},{"id":"d","text":"Gangnam Style — Psy","is_correct":true}],"explanation":"Gangnam Style superó los mil millones de vistas en diciembre de 2012, un hito inédito en YouTube."},{"id":"q8","question":"¿Cómo se llama oficialmente el fandom de BTS?","options":[{"id":"a","text":"EXO-L","is_correct":false},{"id":"b","text":"SONE","is_correct":false},{"id":"c","text":"ARMY","is_correct":true},{"id":"d","text":"VIP","is_correct":false}],"explanation":"ARMY significa Adorable Representative M.C. for Youth; EXO-L es el fandom de EXO y VIP el de BIGBANG."}]'::jsonb,
  null,
  array['k-pop', 'trivia', 'cultura pop', 'música', 'corea']::text[],
  3,
  'published',
  false,
  false,
  now()
)
