insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-k-drama-classics-trivia',
  'K-Drama Classics Trivia: From Winter Sonata to Goblin',
  'Eight questions on the K-dramas that defined a genre: the classics, the terms and the stories behind the Korean Wave on screen.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"Which 2002 drama starring Bae Yong-joon and Choi Ji-woo is credited with igniting the Korean Wave in Japan?","options":[{"id":"a","text":"Full House","is_correct":false},{"id":"b","text":"Winter Sonata","is_correct":true},{"id":"c","text":"Coffee Prince","is_correct":false},{"id":"d","text":"Boys Over Flowers","is_correct":false}],"explanation":"Winter Sonata became such a phenomenon in Japan that Bae Yong-joon is still known there as ''Yonsama''."},{"id":"q2","question":"In ''Jewel in the Palace'' (Dae Jang Geum, 2003), the heroine rises to become what in the Joseon royal court?","options":[{"id":"a","text":"The queen","is_correct":false},{"id":"b","text":"Head of the royal guard","is_correct":false},{"id":"c","text":"The king''s first female royal physician","is_correct":true},{"id":"d","text":"A court painter","is_correct":false}],"explanation":"Jang-geum starts in the royal kitchen and ends as the first woman to serve as physician to a Joseon king."},{"id":"q3","question":"What does the term ''Hallyu'' refer to?","options":[{"id":"a","text":"A Korean honorific for elders","is_correct":false},{"id":"b","text":"The global spread of Korean pop culture","is_correct":true},{"id":"c","text":"A traditional Korean drum","is_correct":false},{"id":"d","text":"The Korean broadcasting awards","is_correct":false}],"explanation":"Hallyu (한류) means ''Korean Wave'': the international boom of Korean dramas, music and film since the late 1990s."},{"id":"q4","question":"''My Love from the Star'' follows Do Min-joon, an alien who landed on Earth during which era?","options":[{"id":"a","text":"The Silla kingdom","is_correct":false},{"id":"b","text":"The Goryeo dynasty","is_correct":false},{"id":"c","text":"The Joseon dynasty","is_correct":true},{"id":"d","text":"The Japanese occupation","is_correct":false}],"explanation":"Do Min-joon arrived in 1609, during the Joseon era, and has lived on Earth for 400 years waiting to return home."},{"id":"q5","question":"''Boys Over Flowers'' (2009) is adapted from what?","options":[{"id":"a","text":"A Korean webtoon","is_correct":false},{"id":"b","text":"A bestselling novel","is_correct":false},{"id":"c","text":"An original screenplay","is_correct":false},{"id":"d","text":"A Japanese manga","is_correct":true}],"explanation":"The drama adapts Yoko Kamio''s manga Hana Yori Dango, already filmed in Taiwan as Meteor Garden."},{"id":"q6","question":"In Korean TV, what is a ''sageuk''?","options":[{"id":"a","text":"A romantic comedy","is_correct":false},{"id":"b","text":"A historical period drama","is_correct":true},{"id":"c","text":"A crime thriller","is_correct":false},{"id":"d","text":"A variety show","is_correct":false}],"explanation":"Sageuk (사극) covers dramas set in historical periods, from palace intrigue to folk tales of old Korea."},{"id":"q7","question":"In ''Goblin'' (2016), the immortal goblin can only die when who pulls the sword from his chest?","options":[{"id":"a","text":"His bride","is_correct":true},{"id":"b","text":"A grim reaper","is_correct":false},{"id":"c","text":"His first love","is_correct":false},{"id":"d","text":"The king who betrayed him","is_correct":false}],"explanation":"The dokkaebi Kim Shin was cursed with immortality; only the prophesied goblin''s bride can remove the sword."},{"id":"q8","question":"''Descendants of the Sun'' (2016) tells the romance between a special forces captain and a what?","options":[{"id":"a","text":"A war correspondent","is_correct":false},{"id":"b","text":"A detective","is_correct":false},{"id":"c","text":"A chef","is_correct":false},{"id":"d","text":"A doctor","is_correct":true}],"explanation":"A soldier and a surgeon fall in love while deployed in the fictional country of Uruk."}]'::jsonb,
  null,
  array['k-drama', 'trivia', 'pop culture', 'tv', 'korea']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-k-dramas-clasicos',
  'Trivia de K-dramas clásicos: de Winter Sonata a Goblin',
  'Ocho preguntas sobre los K-dramas que definieron un género: los clásicos, los términos y las historias tras la ola coreana.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"¿Qué drama de 2002 con Bae Yong-joon y Choi Ji-woo encendió la ola coreana en Japón?","options":[{"id":"a","text":"Full House","is_correct":false},{"id":"b","text":"Winter Sonata","is_correct":true},{"id":"c","text":"Coffee Prince","is_correct":false},{"id":"d","text":"Boys Over Flowers","is_correct":false}],"explanation":"Winter Sonata fue tal fenómeno en Japón que a Bae Yong-joon aún lo conocen allí como ''Yonsama''."},{"id":"q2","question":"En ''Una joya en el palacio'' (Dae Jang Geum, 2003), la heroína llega a ser qué en la corte de Joseon?","options":[{"id":"a","text":"La reina","is_correct":false},{"id":"b","text":"La jefa de la guardia real","is_correct":false},{"id":"c","text":"La primera médica real del rey","is_correct":true},{"id":"d","text":"Una pintora de la corte","is_correct":false}],"explanation":"Jang-geum empieza en la cocina real y termina como la primera mujer médico de un rey de Joseon."},{"id":"q3","question":"¿A qué se refiere el término ''Hallyu''?","options":[{"id":"a","text":"Un tratamiento coreano para los mayores","is_correct":false},{"id":"b","text":"La expansión global de la cultura pop coreana","is_correct":true},{"id":"c","text":"Un tambor tradicional coreano","is_correct":false},{"id":"d","text":"Los premios de la televisión coreana","is_correct":false}],"explanation":"Hallyu (한류) significa ''ola coreana'': el auge internacional de dramas, música y cine de Corea desde finales de los 90."},{"id":"q4","question":"''Mi amor de las estrellas'' sigue a Do Min-joon, un alienígena que llegó a la Tierra durante qué época?","options":[{"id":"a","text":"El reino de Silla","is_correct":false},{"id":"b","text":"La dinastía Goryeo","is_correct":false},{"id":"c","text":"La dinastía Joseon","is_correct":true},{"id":"d","text":"La ocupación japonesa","is_correct":false}],"explanation":"Do Min-joon llegó en 1609, en plena era Joseon, y lleva 400 años en la Tierra esperando volver a casa."},{"id":"q5","question":"¿En qué se basa ''Boys Over Flowers'' (2009)?","options":[{"id":"a","text":"Un webtoon coreano","is_correct":false},{"id":"b","text":"Una novela superventas","is_correct":false},{"id":"c","text":"Un guion original","is_correct":false},{"id":"d","text":"Un manga japonés","is_correct":true}],"explanation":"El drama adapta el manga Hana Yori Dango de Yoko Kamio, ya llevado a la tele en Taiwán como Meteor Garden."},{"id":"q6","question":"En la televisión coreana, ¿qué es un ''sageuk''?","options":[{"id":"a","text":"Una comedia romántica","is_correct":false},{"id":"b","text":"Un drama histórico de época","is_correct":true},{"id":"c","text":"Un thriller policial","is_correct":false},{"id":"d","text":"Un programa de variedades","is_correct":false}],"explanation":"Sageuk (사극) abarca los dramas ambientados en épocas históricas, de intrigas de palacio a relatos populares."},{"id":"q7","question":"En ''Goblin'' (2016), el duende inmortal solo puede morir cuando quién saque la espada de su pecho?","options":[{"id":"a","text":"Su novia destinada","is_correct":true},{"id":"b","text":"Un segador","is_correct":false},{"id":"c","text":"Su primer amor","is_correct":false},{"id":"d","text":"El rey que lo traicionó","is_correct":false}],"explanation":"El dokkaebi Kim Shin fue condenado a la inmortalidad; solo la novia del duende puede retirar la espada."},{"id":"q8","question":"''Descendientes del sol'' (2016) cuenta el romance entre un capitán de fuerzas especiales y quién?","options":[{"id":"a","text":"Una corresponsal de guerra","is_correct":false},{"id":"b","text":"Una detective","is_correct":false},{"id":"c","text":"Una chef","is_correct":false},{"id":"d","text":"Una médica","is_correct":true}],"explanation":"Un soldado y una cirujana se enamoran durante su misión en el país ficticio de Uruk."}]'::jsonb,
  null,
  array['k-drama', 'trivia', 'cultura pop', 'televisión', 'corea']::text[],
  3,
  'published',
  false,
  false,
  now()
)
