insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-korean-culture-trivia',
  'Korean Culture Trivia: Hangul, Hanbok, Kimchi and Festivals',
  'Eight questions on everyday Korean culture: the alphabet invented by a king, the food that ferments and the festivals that fill the year.',
  'trivia',
  'easy',
  'en',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"Hangul, the Korean alphabet, was created in 1443 under which ruler?","options":[{"id":"a","text":"King Taejo","is_correct":false},{"id":"b","text":"King Sejong the Great","is_correct":true},{"id":"c","text":"King Jeongjo","is_correct":false},{"id":"d","text":"Emperor Gojong","is_correct":false}],"explanation":"Sejong commissioned Hangul and promulgated it in 1446 as Hunminjeongeum, ''the correct sounds for instructing the people''."},{"id":"q2","question":"What is the ''hanbok''?","options":[{"id":"a","text":"A ceremonial drum","is_correct":false},{"id":"b","text":"A traditional rice wine","is_correct":false},{"id":"c","text":"Korea''s traditional garment","is_correct":true},{"id":"d","text":"A type of temple roof","is_correct":false}],"explanation":"The hanbok is the traditional Korean dress, with its jeogori jacket and chima skirt or baji trousers."},{"id":"q3","question":"The most common kimchi is made by fermenting which vegetable with chili and salt?","options":[{"id":"a","text":"Napa cabbage","is_correct":true},{"id":"b","text":"Spinach","is_correct":false},{"id":"c","text":"Soybean sprouts","is_correct":false},{"id":"d","text":"Seaweed","is_correct":false}],"explanation":"Baechu kimchi uses napa cabbage; radish (kkakdugi) and cucumber versions exist, but cabbage is the icon."},{"id":"q4","question":"Chuseok, one of Korea''s biggest holidays, celebrates what?","options":[{"id":"a","text":"The first full moon of the year","is_correct":false},{"id":"b","text":"Buddha''s birthday","is_correct":false},{"id":"c","text":"The autumn harvest","is_correct":true},{"id":"d","text":"The winter solstice","is_correct":false}],"explanation":"Chuseok falls on the 15th day of the 8th lunar month: families gather, honor ancestors and share songpyeon rice cakes."},{"id":"q5","question":"What do Koreans traditionally eat on Seollal, the Lunar New Year, to mark gaining a year?","options":[{"id":"a","text":"Kimchi jjigae","is_correct":false},{"id":"b","text":"Tteokguk","is_correct":true},{"id":"c","text":"Samgyetang","is_correct":false},{"id":"d","text":"Bibimbap","is_correct":false}],"explanation":"Tteokguk is a clear broth with sliced rice cakes; a bowl on New Year''s Day symbolizes turning a year older."},{"id":"q6","question":"What is ''kimjang'', the tradition UNESCO added to its heritage list in 2013?","options":[{"id":"a","text":"A royal banquet for the harvest","is_correct":false},{"id":"b","text":"A village wrestling festival","is_correct":false},{"id":"c","text":"A market for winter spices","is_correct":false},{"id":"d","text":"The communal making of kimchi for winter","is_correct":true}],"explanation":"Every autumn, families and neighbors prepare huge batches of kimchi together to last through winter."},{"id":"q7","question":"Which Korean martial art became a full Olympic medal sport at Sydney 2000?","options":[{"id":"a","text":"Taekwondo","is_correct":true},{"id":"b","text":"Judo","is_correct":false},{"id":"c","text":"Karate","is_correct":false},{"id":"d","text":"Ssireum","is_correct":false}],"explanation":"Taekwondo debuted as an official medal sport in Sydney 2000; ssireum is Korea''s traditional wrestling, not Olympic."},{"id":"q8","question":"What is a ''noraebang''?","options":[{"id":"a","text":"A public bathhouse","is_correct":false},{"id":"b","text":"A private karaoke singing room","is_correct":true},{"id":"c","text":"A PC gaming room","is_correct":false},{"id":"d","text":"A traditional tea house","is_correct":false}],"explanation":"Noraebang literally means ''song room'': private karaoke rooms found on nearly every Korean street corner."}]'::jsonb,
  null,
  array['korean culture', 'trivia', 'hangul', 'kimchi', 'korea']::text[],
  3,
  'published',
  false,
  false,
  now()
)
