insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-cultura-coreana',
  'Trivia de cultura coreana: hangul, hanbok, kimchi y fiestas',
  'Ocho preguntas sobre la cultura coreana de cada día: el alfabeto inventado por un rey, la comida fermentada y sus grandes fiestas.',
  'trivia',
  'easy',
  'es',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"El hangul, el alfabeto coreano, fue creado en 1443 bajo qué monarca?","options":[{"id":"a","text":"El rey Taejo","is_correct":false},{"id":"b","text":"El rey Sejong el Grande","is_correct":true},{"id":"c","text":"El rey Jeongjo","is_correct":false},{"id":"d","text":"El emperador Gojong","is_correct":false}],"explanation":"Sejong encargó el hangul y lo promulgó en 1446 como Hunminjeongeum, ''los sonidos correctos para instruir al pueblo''."},{"id":"q2","question":"¿Qué es el ''hanbok''?","options":[{"id":"a","text":"Un tambor ceremonial","is_correct":false},{"id":"b","text":"Un vino tradicional de arroz","is_correct":false},{"id":"c","text":"El traje tradicional de Corea","is_correct":true},{"id":"d","text":"Un tipo de tejado de templo","is_correct":false}],"explanation":"El hanbok es el traje tradicional coreano, con su chaqueta jeogori y la falda chima o el pantalón baji."},{"id":"q3","question":"El kimchi más común se prepara fermentando qué verdura con chile y sal?","options":[{"id":"a","text":"Col china","is_correct":true},{"id":"b","text":"Espinaca","is_correct":false},{"id":"c","text":"Brotes de soja","is_correct":false},{"id":"d","text":"Algas","is_correct":false}],"explanation":"El baechu kimchi usa col china; existen versiones con rábano (kkakdugi) o pepino, pero la col es el ícono."},{"id":"q4","question":"Chuseok, una de las fiestas mayores de Corea, celebra qué?","options":[{"id":"a","text":"La primera luna llena del año","is_correct":false},{"id":"b","text":"El nacimiento de Buda","is_correct":false},{"id":"c","text":"La cosecha de otoño","is_correct":true},{"id":"d","text":"El solsticio de invierno","is_correct":false}],"explanation":"Chuseok cae el día 15 del octavo mes lunar: las familias se reúnen, honran a sus ancestros y comparten songpyeon."},{"id":"q5","question":"¿Qué se come tradicionalmente en Seollal, el Año Nuevo lunar, para marcar un año más?","options":[{"id":"a","text":"Kimchi jjigae","is_correct":false},{"id":"b","text":"Tteokguk","is_correct":true},{"id":"c","text":"Samgyetang","is_correct":false},{"id":"d","text":"Bibimbap","is_correct":false}],"explanation":"El tteokguk es un caldo claro con rebanadas de pastel de arroz; un plato en Año Nuevo simboliza cumplir un año más."},{"id":"q6","question":"¿Qué es el ''kimjang'', la tradición que la UNESCO declaró patrimonio en 2013?","options":[{"id":"a","text":"Un banquete real por la cosecha","is_correct":false},{"id":"b","text":"Un festival de lucha entre aldeas","is_correct":false},{"id":"c","text":"Un mercado de especias de invierno","is_correct":false},{"id":"d","text":"La elaboración comunitaria de kimchi para el invierno","is_correct":true}],"explanation":"Cada otoño, familias y vecinos preparan juntos enormes tandas de kimchi para pasar el invierno."},{"id":"q7","question":"¿Qué arte marcial coreano debutó como deporte oficial de medallas en Sídney 2000?","options":[{"id":"a","text":"Taekwondo","is_correct":true},{"id":"b","text":"Judo","is_correct":false},{"id":"c","text":"Karate","is_correct":false},{"id":"d","text":"Ssireum","is_correct":false}],"explanation":"El taekwondo se estrenó como deporte oficial en Sídney 2000; el ssireum es la lucha tradicional coreana, no olímpica."},{"id":"q8","question":"¿Qué es un ''noraebang''?","options":[{"id":"a","text":"Un baño público","is_correct":false},{"id":"b","text":"Una sala privada de karaoke","is_correct":true},{"id":"c","text":"Una sala de videojuegos","is_correct":false},{"id":"d","text":"Una casa de té tradicional","is_correct":false}],"explanation":"Noraebang significa literalmente ''cuarto de canciones'': salas privadas de karaoke en casi cada esquina de Corea."}]'::jsonb,
  null,
  array['cultura coreana', 'trivia', 'hangul', 'kimchi', 'corea']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-what-k-pop-role-fits-you',
  'Which K-Pop Role Would You Have in a Group?',
  'Leader, main vocal, main dancer or maknae? Eight questions reveal the role you''d actually play if you debuted in a K-pop group.',
  'personality',
  'easy',
  'en',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"Rehearsal runs late and the routine still isn''t clean. You:","options":[{"id":"a","text":"Stay until everyone nails it, keeping spirits up.","personality_tags":["leader"]},{"id":"b","text":"Drill your own part alone until it''s perfect.","personality_tags":["dancer"]},{"id":"c","text":"Record yourself singing the tricky part until it sounds right.","personality_tags":["vocal"]},{"id":"d","text":"Crack a joke and order food for the team.","personality_tags":["maknae"]}],"explanation":null,"time_limit_seconds":30},{"id":"q2","question":"Your friends come to you when they need:","options":[{"id":"a","text":"Someone to make the hard call.","personality_tags":["leader"]},{"id":"b","text":"Someone who listens and really feels it with them.","personality_tags":["vocal"]},{"id":"c","text":"A push to get up and actually do the thing.","personality_tags":["dancer"]},{"id":"d","text":"A distraction and a reason to laugh.","personality_tags":["maknae"]}],"explanation":null,"time_limit_seconds":30},{"id":"q3","question":"In the group photo you''re:","options":[{"id":"a","text":"Slightly behind, checking everyone fits in frame.","personality_tags":["leader"]},{"id":"b","text":"The one whose expression makes the shot.","personality_tags":["vocal"]},{"id":"c","text":"Mid-pose, body line exactly right.","personality_tags":["dancer"]},{"id":"d","text":"Doing something silly at the edge.","personality_tags":["maknae"]}],"explanation":null,"time_limit_seconds":30},{"id":"q4","question":"Pick a stage moment:","options":[{"id":"a","text":"The quiet second before the song starts.","personality_tags":["leader"]},{"id":"b","text":"The high note that gives the crowd chills.","personality_tags":["vocal"]},{"id":"c","text":"The dance break.","personality_tags":["dancer"]},{"id":"d","text":"The fan-service bit that melts the front row.","personality_tags":["maknae"]}],"explanation":null,"time_limit_seconds":30},{"id":"q5","question":"Your practice playlist is mostly:","options":[{"id":"a","text":"Whatever the group needs to run next.","personality_tags":["leader"]},{"id":"b","text":"Ballads and vocal warm-ups.","personality_tags":["vocal"]},{"id":"c","text":"Anything with a beat you can choreograph to.","personality_tags":["dancer"]},{"id":"d","text":"The latest viral tracks everyone is covering.","personality_tags":["maknae"]}],"explanation":null,"time_limit_seconds":30},{"id":"q6","question":"A mic fails mid-song at your first live show. You:","options":[{"id":"a","text":"Cover the gap and calm everyone down after.","personality_tags":["leader"]},{"id":"b","text":"Sing louder so nobody notices.","personality_tags":["vocal"]},{"id":"c","text":"Fold it into the choreography.","personality_tags":["dancer"]},{"id":"d","text":"Make the audience laugh until it''s fixed.","personality_tags":["maknae"]}],"explanation":null,"time_limit_seconds":30},{"id":"q7","question":"Your trainee journal would be full of:","options":[{"id":"a","text":"Schedules, checklists and notes to self.","personality_tags":["leader"]},{"id":"b","text":"Lyrics and melodies.","personality_tags":["vocal"]},{"id":"c","text":"Practice videos to review frame by frame.","personality_tags":["dancer"]},{"id":"d","text":"Doodles, inside jokes and snack reviews.","personality_tags":["maknae"]}],"explanation":null,"time_limit_seconds":30},{"id":"q8","question":"The fans would love you most for:","options":[{"id":"a","text":"How you hold the group together.","personality_tags":["leader"]},{"id":"b","text":"The voice they recognize in one note.","personality_tags":["vocal"]},{"id":"c","text":"The fancams that go viral.","personality_tags":["dancer"]},{"id":"d","text":"The chaos you bring to variety shows.","personality_tags":["maknae"]}],"explanation":null,"time_limit_seconds":30}]'::jsonb,
  '[{"id":"r1","title":"The Leader","description":"You hold the center: calm under pressure, first to take responsibility, last to take credit. The group works because you keep it working.","personality_tag":"leader","background_theme":"stars"},{"id":"r2","title":"The Main Vocal","description":"You feel everything and it shows in your voice. Yours is the high note that turns a performance into a memory.","personality_tag":"vocal","background_theme":"mystic"},{"id":"r3","title":"The Main Dancer","description":"Discipline disguised as instinct. You live in the practice room, and on stage your body says what words can''t.","personality_tag":"dancer","background_theme":"fire"},{"id":"r4","title":"The Maknae","description":"The youngest energy the whole group protects and secretly envies. You bring the laughter, the chaos and the heart.","personality_tag":"maknae","background_theme":"ocean"}]'::jsonb,
  array['personality quiz', 'k-pop', 'pop culture', 'korea']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-que-rol-tendrias-en-un-grupo-de-k-pop',
  '¿Qué rol tendrías en un grupo de K-pop?',
  '¿Líder, vocalista principal, bailarín estrella o maknae? Ocho preguntas revelan el rol que tendrías si debutaras en un grupo de K-pop.',
  'personality',
  'easy',
  'es',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"El ensayo se alarga y la coreografía aún no sale. Tú:","options":[{"id":"a","text":"Te quedas hasta que a todos les salga, con el ánimo arriba.","personality_tags":["lider"]},{"id":"b","text":"Repites tu parte a solas hasta que quede perfecta.","personality_tags":["bailarin"]},{"id":"c","text":"Te grabas cantando la parte difícil hasta que suene bien.","personality_tags":["vocal"]},{"id":"d","text":"Sueltas un chiste y pides comida para el equipo.","personality_tags":["maknae"]}],"explanation":null,"time_limit_seconds":30},{"id":"q2","question":"Tus amigos te buscan cuando necesitan:","options":[{"id":"a","text":"A alguien que tome la decisión difícil.","personality_tags":["lider"]},{"id":"b","text":"A alguien que escuche y sienta de verdad con ellos.","personality_tags":["vocal"]},{"id":"c","text":"Un empujón para levantarse y hacerlo de una vez.","personality_tags":["bailarin"]},{"id":"d","text":"Una distracción y un motivo para reír.","personality_tags":["maknae"]}],"explanation":null,"time_limit_seconds":30},{"id":"q3","question":"En la foto grupal eres quien:","options":[{"id":"a","text":"Se pone un poco atrás, verificando que todos salgan.","personality_tags":["lider"]},{"id":"b","text":"Pone la expresión que salva la foto.","personality_tags":["vocal"]},{"id":"c","text":"Pone la pose con la línea del cuerpo exacta.","personality_tags":["bailarin"]},{"id":"d","text":"Hace algo gracioso en una esquina.","personality_tags":["maknae"]}],"explanation":null,"time_limit_seconds":30},{"id":"q4","question":"Elige un momento del escenario:","options":[{"id":"a","text":"El segundo de silencio antes de que empiece la canción.","personality_tags":["lider"]},{"id":"b","text":"La nota alta que pone la piel de gallina.","personality_tags":["vocal"]},{"id":"c","text":"El dance break.","personality_tags":["bailarin"]},{"id":"d","text":"El guiño al público que derrite la primera fila.","personality_tags":["maknae"]}],"explanation":null,"time_limit_seconds":30},{"id":"q5","question":"Tu playlist de ensayo tiene sobre todo:","options":[{"id":"a","text":"Lo que el grupo necesite ensayar después.","personality_tags":["lider"]},{"id":"b","text":"Baladas y calentamientos vocales.","personality_tags":["vocal"]},{"id":"c","text":"Cualquier cosa con ritmo para coreografiar.","personality_tags":["bailarin"]},{"id":"d","text":"Los últimos temas virales que todos versionan.","personality_tags":["maknae"]}],"explanation":null,"time_limit_seconds":30},{"id":"q6","question":"Un micrófono falla a mitad de canción en tu primer concierto. Tú:","options":[{"id":"a","text":"Cubres el hueco y calmas a todos después.","personality_tags":["lider"]},{"id":"b","text":"Cantas más fuerte para que nadie lo note.","personality_tags":["vocal"]},{"id":"c","text":"Lo conviertes en parte de la coreografía.","personality_tags":["bailarin"]},{"id":"d","text":"Haces reír al público mientras lo arreglan.","personality_tags":["maknae"]}],"explanation":null,"time_limit_seconds":30},{"id":"q7","question":"Tu diario de aprendiz estaría lleno de:","options":[{"id":"a","text":"Horarios, listas y notas para ti mismo.","personality_tags":["lider"]},{"id":"b","text":"Letras y melodías.","personality_tags":["vocal"]},{"id":"c","text":"Videos de práctica para revisar fotograma a fotograma.","personality_tags":["bailarin"]},{"id":"d","text":"Garabatos, chistes internos y reseñas de snacks.","personality_tags":["maknae"]}],"explanation":null,"time_limit_seconds":30},{"id":"q8","question":"Los fans te querrían sobre todo por:","options":[{"id":"a","text":"La forma en que mantienes unido al grupo.","personality_tags":["lider"]},{"id":"b","text":"La voz que reconocen en una sola nota.","personality_tags":["vocal"]},{"id":"c","text":"Los fancams que se vuelven virales.","personality_tags":["bailarin"]},{"id":"d","text":"El caos que traes a los programas de variedades.","personality_tags":["maknae"]}],"explanation":null,"time_limit_seconds":30}]'::jsonb,
  '[{"id":"r1","title":"El líder","description":"Eres el centro que sostiene todo: sereno bajo presión, el primero en asumir responsabilidad y el último en pedir crédito. El grupo funciona porque tú lo haces funcionar.","personality_tag":"lider","background_theme":"stars"},{"id":"r2","title":"El vocalista principal","description":"Lo sientes todo y se nota en tu voz. Tuya es la nota alta que convierte una presentación en un recuerdo.","personality_tag":"vocal","background_theme":"mystic"},{"id":"r3","title":"El bailarín principal","description":"Disciplina disfrazada de instinto. Vives en la sala de ensayo y en el escenario tu cuerpo dice lo que las palabras no pueden.","personality_tag":"bailarin","background_theme":"fire"},{"id":"r4","title":"El maknae","description":"La energía del menor que todo el grupo protege y en secreto envidia. Tú traes la risa, el caos y el corazón.","personality_tag":"maknae","background_theme":"ocean"}]'::jsonb,
  array['test de personalidad', 'k-pop', 'cultura pop', 'corea']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-which-k-drama-genre-is-your-life',
  'Which K-Drama Genre Is Your Life?',
  'Is your life a slow-burn romance, a palace intrigue, a revenge thriller or a healing slice of life? Eight questions, one genre.',
  'personality',
  'easy',
  'en',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"Your group chat is mostly full of:","options":[{"id":"a","text":"Detailed analysis of who texted back and when.","personality_tags":["romance"]},{"id":"b","text":"Long-term plans and carefully built alliances.","personality_tags":["sageuk"]},{"id":"c","text":"Wild theories about what''s really going on.","personality_tags":["thriller"]},{"id":"d","text":"Memes, food photos and dinner plans.","personality_tags":["healing"]}],"explanation":null,"time_limit_seconds":30},{"id":"q2","question":"Choose a setting for your Friday night:","options":[{"id":"a","text":"A rooftop dinner at golden hour.","personality_tags":["romance"]},{"id":"b","text":"A museum exhibit about an old dynasty.","personality_tags":["sageuk"]},{"id":"c","text":"An escape room.","personality_tags":["thriller"]},{"id":"d","text":"A slow dinner at a friend''s countryside place.","personality_tags":["healing"]}],"explanation":null,"time_limit_seconds":30},{"id":"q3","question":"When someone wrongs you:","options":[{"id":"a","text":"You replay every interaction for days.","personality_tags":["romance"]},{"id":"b","text":"You wait for the right moment, patient as a strategist.","personality_tags":["sageuk"]},{"id":"c","text":"You file it away — everything comes back around.","personality_tags":["thriller"]},{"id":"d","text":"You shrug it off over a good meal.","personality_tags":["healing"]}],"explanation":null,"time_limit_seconds":30},{"id":"q4","question":"Your ideal plot twist:","options":[{"id":"a","text":"The leads finally confess in the rain.","personality_tags":["romance"]},{"id":"b","text":"The humble advisor turns out to have royal blood.","personality_tags":["sageuk"]},{"id":"c","text":"The villain was the narrator all along.","personality_tags":["thriller"]},{"id":"d","text":"No twist — everyone ends up happy at the table.","personality_tags":["healing"]}],"explanation":null,"time_limit_seconds":30},{"id":"q5","question":"Your life''s recurring soundtrack would be:","options":[{"id":"a","text":"A ballad that swells at exactly the right moment.","personality_tags":["romance"]},{"id":"b","text":"Strings and traditional instruments.","personality_tags":["sageuk"]},{"id":"c","text":"A tense pulse that never lets up.","personality_tags":["thriller"]},{"id":"d","text":"Warm acoustic guitar.","personality_tags":["healing"]}],"explanation":null,"time_limit_seconds":30},{"id":"q6","question":"In your family you''re the one who:","options":[{"id":"a","text":"Cries at weddings and remembers every anniversary.","personality_tags":["romance"]},{"id":"b","text":"Knows the whole family history by heart.","personality_tags":["sageuk"]},{"id":"c","text":"Finds everything out first.","personality_tags":["thriller"]},{"id":"d","text":"Keeps everyone fed.","personality_tags":["healing"]}],"explanation":null,"time_limit_seconds":30},{"id":"q7","question":"Your dream plot device:","options":[{"id":"a","text":"A fated first meeting that repeats years later.","personality_tags":["romance"]},{"id":"b","text":"A hidden identity that changes everything.","personality_tags":["sageuk"]},{"id":"c","text":"An episode-16 cliffhanger solved in the finale.","personality_tags":["thriller"]},{"id":"d","text":"Neighbors slowly becoming family.","personality_tags":["healing"]}],"explanation":null,"time_limit_seconds":30},{"id":"q8","question":"Pick a K-drama archetype to live as:","options":[{"id":"a","text":"The lead with two perfect suitors.","personality_tags":["romance"]},{"id":"b","text":"The royal heir in disguise.","personality_tags":["sageuk"]},{"id":"c","text":"The wronged hero planning the comeback.","personality_tags":["thriller"]},{"id":"d","text":"The big-city doctor who moves to a small village.","personality_tags":["healing"]}],"explanation":null,"time_limit_seconds":30}]'::jsonb,
  '[{"id":"r1","title":"Slow-Burn Romance","description":"Your life runs on meaningful looks and almost-confessions. Every rainy day is a scene waiting for an umbrella.","personality_tag":"romance","background_theme":"ocean"},{"id":"r2","title":"Sageuk Intrigue","description":"Palace politics, old debts and quiet honor: you play the long game and never reveal your hand early.","personality_tag":"sageuk","background_theme":"stars"},{"id":"r3","title":"Revenge Thriller","description":"Every week of your life ends on a cliffhanger. You keep receipts, connect dots and always know more than you say.","personality_tag":"thriller","background_theme":"fire"},{"id":"r4","title":"Healing Slice of Life","description":"Warm kitchens, found family and small towns where everyone knows your name. Your plot armor is kindness.","personality_tag":"healing","background_theme":"forest"}]'::jsonb,
  array['personality quiz', 'k-drama', 'pop culture', 'korea']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-que-genero-de-k-drama-es-tu-vida',
  '¿Qué género de K-drama es tu vida?',
  '¿Es tu vida un romance lento, una intriga de palacio, un thriller de venganza o una historia sanadora? Ocho preguntas, un género.',
  'personality',
  'easy',
  'es',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"Tu chat de grupo está lleno sobre todo de:","options":[{"id":"a","text":"Análisis detallados de quién contestó y cuándo.","personality_tags":["romance"]},{"id":"b","text":"Planes a largo plazo y alianzas bien construidas.","personality_tags":["sageuk"]},{"id":"c","text":"Teorías descabelladas sobre lo que pasa de verdad.","personality_tags":["thriller"]},{"id":"d","text":"Memes, fotos de comida y planes de cena.","personality_tags":["healing"]}],"explanation":null,"time_limit_seconds":30},{"id":"q2","question":"Elige un plan para tu viernes por la noche:","options":[{"id":"a","text":"Una cena en una azotea a la hora dorada.","personality_tags":["romance"]},{"id":"b","text":"Una exposición de museo sobre una dinastía antigua.","personality_tags":["sageuk"]},{"id":"c","text":"Un escape room.","personality_tags":["thriller"]},{"id":"d","text":"Una cena tranquila en la casa de campo de un amigo.","personality_tags":["healing"]}],"explanation":null,"time_limit_seconds":30},{"id":"q3","question":"Cuando alguien te hace algo malo:","options":[{"id":"a","text":"Repasas cada interacción durante días.","personality_tags":["romance"]},{"id":"b","text":"Esperas el momento justo, paciente como un estratega.","personality_tags":["sageuk"]},{"id":"c","text":"Lo archivas: todo vuelve tarde o temprano.","personality_tags":["thriller"]},{"id":"d","text":"Lo olvidas frente a una buena comida.","personality_tags":["healing"]}],"explanation":null,"time_limit_seconds":30},{"id":"q4","question":"Tu giro de guion ideal:","options":[{"id":"a","text":"Los protagonistas por fin se confiesan bajo la lluvia.","personality_tags":["romance"]},{"id":"b","text":"El humilde consejero resulta tener sangre real.","personality_tags":["sageuk"]},{"id":"c","text":"El villano era el narrador todo el tiempo.","personality_tags":["thriller"]},{"id":"d","text":"Sin giro: todos terminan felices en la mesa.","personality_tags":["healing"]}],"explanation":null,"time_limit_seconds":30},{"id":"q5","question":"La banda sonora de tu vida sería:","options":[{"id":"a","text":"Una balada que crece justo en el momento exacto.","personality_tags":["romance"]},{"id":"b","text":"Cuerdas e instrumentos tradicionales.","personality_tags":["sageuk"]},{"id":"c","text":"Un pulso tenso que nunca cede.","personality_tags":["thriller"]},{"id":"d","text":"Guitarra acústica cálida.","personality_tags":["healing"]}],"explanation":null,"time_limit_seconds":30},{"id":"q6","question":"En tu familia eres quien:","options":[{"id":"a","text":"Llora en las bodas y recuerda cada aniversario.","personality_tags":["romance"]},{"id":"b","text":"Se sabe de memoria toda la historia familiar.","personality_tags":["sageuk"]},{"id":"c","text":"Se entera de todo primero.","personality_tags":["thriller"]},{"id":"d","text":"Mantiene a todos bien comidos.","personality_tags":["healing"]}],"explanation":null,"time_limit_seconds":30},{"id":"q7","question":"Tu recurso de guion soñado:","options":[{"id":"a","text":"Un primer encuentro marcado por el destino que se repite años después.","personality_tags":["romance"]},{"id":"b","text":"Una identidad oculta que lo cambia todo.","personality_tags":["sageuk"]},{"id":"c","text":"Un suspenso de episodio 16 que se resuelve en el final.","personality_tags":["thriller"]},{"id":"d","text":"Vecinos que poco a poco se vuelven familia.","personality_tags":["healing"]}],"explanation":null,"time_limit_seconds":30},{"id":"q8","question":"Elige un arquetipo de K-drama para vivir:","options":[{"id":"a","text":"El protagonista con dos pretendientes perfectos.","personality_tags":["romance"]},{"id":"b","text":"El heredero de la corona disfrazado.","personality_tags":["sageuk"]},{"id":"c","text":"El héroe agraviado que planea su regreso.","personality_tags":["thriller"]},{"id":"d","text":"El médico de ciudad que se muda a un pueblo pequeño.","personality_tags":["healing"]}],"explanation":null,"time_limit_seconds":30}]'::jsonb,
  '[{"id":"r1","title":"Romance de cocción lenta","description":"Tu vida funciona a base de miradas que significan algo y confesiones que casi salen. Cada día de lluvia es una escena esperando un paraguas.","personality_tag":"romance","background_theme":"ocean"},{"id":"r2","title":"Intriga de palacio","description":"Política de corte, deudas antiguas y honor silencioso: juegas a largo plazo y nunca muestras tu mano antes de tiempo.","personality_tag":"sageuk","background_theme":"stars"},{"id":"r3","title":"Thriller de venganza","description":"Cada semana de tu vida termina en un suspenso. Guardas los recibos, unes los puntos y siempre sabes más de lo que dices.","personality_tag":"thriller","background_theme":"fire"},{"id":"r4","title":"Historia sanadora","description":"Cocinas cálidas, familia encontrada y pueblos pequeños donde todos saben tu nombre. Tu escudo es la amabilidad.","personality_tag":"healing","background_theme":"forest"}]'::jsonb,
  array['test de personalidad', 'k-drama', 'cultura pop', 'corea']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

-- categories.quiz_count is maintained by the trigger on quizzes.

